'use strict';

// ------------------------- Utilidades -------------------------
const $  = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

function fmtNum(n) {
  if (n == null || isNaN(n)) return '—';
  return Number(n).toLocaleString('es-AR');
}

function fmtFecha(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  const pad = (x) => String(x).padStart(2, '0');
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

// Tiempo relativo compacto en castellano ("hace 3 min", "hace 2 h", "hace 4 d",
// "hace 2 mes", "hace 1 a"). Sin dependencias; equivalente al
// $oTiempo->traducir($oTiempo->diferencia(...)) del legacy.
function fmtHace(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d)) return '';
  const diff = Math.max(0, (Date.now() - d.getTime()) / 1000); // en segundos
  if (diff < 60)         return 'hace ' + Math.floor(diff)         + ' s';
  if (diff < 3600)       return 'hace ' + Math.floor(diff / 60)    + ' min';
  if (diff < 86400)      return 'hace ' + Math.floor(diff / 3600)  + ' h';
  if (diff < 2592000)    return 'hace ' + Math.floor(diff / 86400) + ' d';
  if (diff < 31536000)   return 'hace ' + Math.floor(diff / 2592000)  + ' mes';
  return 'hace ' + Math.floor(diff / 31536000) + ' a';
}

// Version verbose de fmtHace: "hace 2 horas", "hace 3 dias" — con singular/plural
// y palabras completas. Pensado para tarjetas donde importa la lectura natural.
function fmtHaceLargo(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d)) return '';
  const diff = Math.max(0, (Date.now() - d.getTime()) / 1000);
  const plural = (n, sing, plu) => `hace ${n} ${n === 1 ? sing : plu}`;
  if (diff < 60)       return plural(Math.floor(diff),               'segundo', 'segundos');
  if (diff < 3600)     return plural(Math.floor(diff / 60),           'minuto', 'minutos');
  if (diff < 86400)    return plural(Math.floor(diff / 3600),         'hora',   'horas');
  if (diff < 2592000)  return plural(Math.floor(diff / 86400),        'día',    'días');
  if (diff < 31536000) return plural(Math.floor(diff / 2592000),      'mes',    'meses');
  return                      plural(Math.floor(diff / 31536000),     'año',    'años');
}

// YYYY-MM-DD HH:MM:SS — para listados donde importa el segundo (log de mensajes).
function fmtFechaLarga(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  const pad = (x) => String(x).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

// Cabecera de tabla ordenable. Devuelve el HTML del <th> para una columna
// que dispara sort al hacer click. `col` es la clave que se pasa al backend
// (matchea el `orderMap` del endpoint). El indicador ↑/↓ lo pinta
// `actualizarSortIndicadores` en base al estado actual del filtro.
function thOrdenable(col, label, extra = '') {
  return `<th data-sort="${col}" style="cursor:pointer;user-select:none${extra ? ';' + extra : ''}">`
       + `${label} <span data-sort-ind style="color:var(--muted);font-size:.85em"></span></th>`;
}

// Sincroniza los indicadores ↑/↓ de un thead con el filtro (order_by + dir).
function actualizarSortIndicadores(theadRoot, filtros) {
  if (!theadRoot) return;
  theadRoot.querySelectorAll('th[data-sort]').forEach((th) => {
    const activo = th.dataset.sort === filtros.order_by;
    const flecha = activo ? (filtros.dir === 'asc' ? '↑' : '↓') : '';
    const ind = th.querySelector('[data-sort-ind]');
    if (ind) ind.textContent = flecha;
    th.style.color = activo ? 'var(--text)' : '';
  });
}

// Wiring del click en el thead: alterna dir si se clickea la misma columna,
// arranca en 'asc' si se clickea otra. Llama a `recargar` despues de mutar
// el filtro. `filtrosRef` es el objeto de filtros (mutado in-place).
function activarSortEnThead(theadEl, filtrosRef, recargar) {
  if (!theadEl || theadEl.dataset.sortWired === '1') return;
  theadEl.dataset.sortWired = '1';
  theadEl.addEventListener('click', (ev) => {
    const th = ev.target.closest('th[data-sort]');
    if (!th) return;
    const col = th.dataset.sort;
    if (filtrosRef.order_by === col) {
      filtrosRef.dir = filtrosRef.dir === 'asc' ? 'desc' : 'asc';
    } else {
      filtrosRef.order_by = col;
      filtrosRef.dir      = 'asc';
    }
    recargar();
  });
}

// Convierte texto libre a un slug dot-separated compatible con la regex
// `^[a-z0-9][a-z0-9._-]*$` que usan `roles.slug` y `permisos.slug`.
// Normaliza a minusculas, quita diacriticos comunes en espanol y colapsa
// cualquier corrida de caracteres no [a-z0-9] a un unico punto. Trunca a 100
// (el maxlength de las columnas `slug` en la BD).
function slugificarConPuntos(txt) {
  if (txt == null) return '';
  return String(txt)
    .toLowerCase()
    .replace(/[áàäâã]/g, 'a')
    .replace(/[éèëê]/g,  'e')
    .replace(/[íìïî]/g,  'i')
    .replace(/[óòöôõ]/g, 'o')
    .replace(/[úùüû]/g,  'u')
    .replace(/ñ/g,       'n')
    .replace(/ç/g,       'c')
    .replace(/[^a-z0-9]+/g, '.')
    .replace(/^\.+/, '')
    .replace(/\.+$/, '')
    .substring(0, 100)
    .replace(/\.+$/, '');
}

// Etiquetas (tags): pills chicas de solo lectura para listados y modales
// Consultar. `compact` = fuente extra chica pensada para no romper la altura
// de fila cuando se muestran debajo del nombre. Devuelve '' si el array es
// vacio (para poder concatenar sin condicionales).
function renderTagsPills(tags, { compact = true } = {}) {
  if (!Array.isArray(tags) || tags.length === 0) return '';
  const fs  = compact ? '.68rem' : '.78rem';
  const pad = compact ? '1px 7px' : '2px 9px';
  const gap = compact ? '3px'     : '5px';
  const mt  = compact ? '3px'     : '4px';
  const pill = (t) => `<span style="display:inline-block;padding:${pad};background:color-mix(in srgb, var(--primary) 22%, transparent);color:var(--text);border:1px solid color-mix(in srgb, var(--primary) 40%, transparent);border-radius:999px;font-size:${fs};line-height:1.2;white-space:nowrap">${esc(t)}</span>`;
  return `<div style="display:flex;flex-wrap:wrap;gap:${gap};margin-top:${mt}">${tags.map(pill).join('')}</div>`;
}

// Editor de tags tipo "chips" para modales de edicion. Renderiza dentro de
// `container` (elemento DOM) un input inline con las pills ya cargadas de
// `initialTags`. Reglas:
//   - Enter o coma = confirma el texto actual como nueva pill
//   - Backspace con el input vacio = borra la ultima pill
//   - Click en la "×" de una pill = la quita
//   - Blur con texto sin confirmar = lo confirma igual (para no perder input)
//   - Tope de 20 tags, 50 chars por tag, colapsado de espacios y dedup
// Devuelve `{ getTags(): string[] }` que el caller invoca al momento de
// armar el payload del PUT.
function attachTagsEditor(container, initialTags) {
  const state = { tags: (Array.isArray(initialTags) ? initialTags : []).slice(0, 20) };
  container.innerHTML = `
    <div data-slot="wrap" style="display:flex;flex-wrap:wrap;gap:6px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;background:var(--surface);min-height:38px;align-items:center;cursor:text">
      <span data-slot="pills" style="display:contents"></span>
      <input type="text" data-slot="input" placeholder="Escribí y Enter para agregar…"
             style="flex:1;min-width:140px;border:0;background:transparent;color:var(--text);outline:none;font-size:.9rem;padding:2px 4px">
    </div>
    <div style="font-size:.72rem;color:var(--muted);margin-top:4px">
      Máx. 20 etiquetas · Enter o coma agrega · Backspace borra la última
    </div>
  `;
  const wrap  = container.querySelector('[data-slot="wrap"]');
  const pills = container.querySelector('[data-slot="pills"]');
  const input = container.querySelector('[data-slot="input"]');

  const pintar = () => {
    pills.innerHTML = state.tags.map((t, i) => `
      <span style="display:inline-flex;align-items:center;gap:2px;padding:2px 4px 2px 10px;background:color-mix(in srgb, var(--primary) 22%, transparent);color:var(--text);border:1px solid color-mix(in srgb, var(--primary) 40%, transparent);border-radius:999px;font-size:.78rem;line-height:1.2;white-space:nowrap">
        ${esc(t)}
        <button type="button" data-remove="${i}" title="Quitar" style="border:0;background:transparent;color:inherit;cursor:pointer;font-size:1rem;line-height:1;padding:0 4px">×</button>
      </span>
    `).join('');
  };

  const agregar = (raw) => {
    const t = String(raw || '').replace(/\s+/g, ' ').trim().slice(0, 50);
    if (!t) return;
    if (state.tags.includes(t)) return;
    if (state.tags.length >= 20) return;
    state.tags.push(t);
    pintar();
  };

  input.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ',') {
      ev.preventDefault();
      agregar(input.value);
      input.value = '';
    } else if (ev.key === 'Backspace' && input.value === '' && state.tags.length) {
      ev.preventDefault();
      state.tags.pop();
      pintar();
    }
  });
  input.addEventListener('blur', () => {
    if (input.value.trim() !== '') { agregar(input.value); input.value = ''; }
  });
  pills.addEventListener('click', (ev) => {
    const b = ev.target.closest('[data-remove]');
    if (!b) return;
    state.tags.splice(Number(b.dataset.remove), 1);
    pintar();
  });
  wrap.addEventListener('click', (ev) => { if (ev.target === wrap) input.focus(); });

  pintar();
  return { getTags: () => state.tags.slice() };
}

async function apiGet(url) {
  const r = await fetch(url, { credentials: 'same-origin' });
  if (r.status === 401) { handleSessionExpired(); throw new Error('Sesión expirada'); }
  const j = await r.json().catch(() => ({ ok: false, error: 'Respuesta no JSON' }));
  if (!r.ok || !j.ok) throw new Error(j.error || `HTTP ${r.status}`);
  return j.data;
}

async function apiSend(url, method, body) {
  const r = await fetch(url, {
    method,
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: body == null ? null : JSON.stringify(body),
  });
  if (r.status === 401) { handleSessionExpired(); throw new Error('Sesión expirada'); }
  const j = await r.json().catch(() => ({ ok: false, error: 'Respuesta no JSON' }));
  if (!r.ok || !j.ok) throw new Error(j.error || `HTTP ${r.status}`);
  return j.data;
}

// Cuando la cookie de sesión vence, cualquier apiGet/apiSend devuelve 401.
// En vez de dejar que cada módulo renderice el error crudo "No autenticado",
// limpiamos el estado local y volvemos a la pantalla de login. Idempotente:
// múltiples requests fallando en paralelo no muestran múltiples toasts ni
// pisan el login que ya está en pantalla.
let _sessionExpiredFlag = false;
function handleSessionExpired() {
  if (_sessionExpiredFlag) return;
  if (!AUTH.user) return; // aún no autenticados: dejá que el flujo de login normal siga
  _sessionExpiredFlag = true;
  AUTH.user  = null;
  AUTH.perms = new Set();
  try { closeModal(); } catch (_) {}
  try { cerrarCtxMenu(); } catch (_) {}
  const view = document.getElementById('view');
  if (view) view.innerHTML = '';
  showLoginScreen();
  toast('Sesión expirada. Ingresá de nuevo.', { error: true });
  setTimeout(() => { _sessionExpiredFlag = false; }, 1500);
}

// ------------------------- Polling de versión -------------------------
// Muestra el banner "nueva versión disponible" (#versionBanner, oculto por
// default en index.php) cuando `version.txt` en el servidor cambia respecto
// al que cargó la página al abrir la pestaña. Se activa después de un
// `git push` + deploy: al próximo poll cada cliente ve el aviso y recarga.
const VERSION_INICIAL = document.getElementById('appVersion')?.textContent?.trim() || '';
async function chequearVersion() {
  try {
    const r = await fetch('api/version.php', { cache: 'no-store' });
    const data = await r.json();
    if (data.ok && data.version && VERSION_INICIAL && data.version !== VERSION_INICIAL) {
      const b = document.getElementById('versionBanner');
      if (b) b.style.display = '';
    }
  } catch (_) { /* silencioso: se reintenta en el próximo tick */ }
}
document.addEventListener('DOMContentLoaded', () => {
  setInterval(chequearVersion, 5000);
});

// ------------------------- Toast -------------------------
function toast(msg, opts = {}) {
  let t = $('#toast');
  if (!t) {
    t = document.createElement('div');
    t.id = 'toast';
    t.className = 'toast';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.classList.toggle('error', !!opts.error);
  t.classList.add('show');
  clearTimeout(toast._h);
  // Errores viven 10s (dan tiempo a leer un stack de mTLS / API); resto 2.4s.
  const defaultDuration = opts.error ? 10000 : 2400;
  const duration = typeof opts.duration === 'number' ? opts.duration : defaultDuration;
  toast._h = setTimeout(() => t.classList.remove('show'), duration);
}

// ------------------------- Modal helpers -------------------------
function openModal(html) {
  closeModal();
  const wrap = document.createElement('div');
  wrap.className = 'modal-backdrop';
  wrap.id = 'modalRoot';
  wrap.innerHTML = html;
  document.body.appendChild(wrap);
  requestAnimationFrame(() => wrap.classList.add('open'));
  wrap.addEventListener('click', (ev) => { if (ev.target === wrap) closeModal(); });
  return wrap;
}
function closeModal() {
  const m = $('#modalRoot');
  if (!m) return;
  // Liberar el id ya para que un openModal() inmediato no quede compitiendo con
  // este nodo durante los 200 ms de animacion de cierre.
  m.id = '';
  m.classList.remove('open');
  setTimeout(() => m.remove(), 200);
}

function confirmar({ title, message, confirmText = 'Confirmar', danger = true }) {
  return new Promise((resolve) => {
    const wrap = document.createElement('div');
    wrap.className = 'confirm-backdrop';
    wrap.innerHTML = `
      <div class="confirm-box">
        <div class="confirm-title">${esc(title)}</div>
        <div class="confirm-msg">${esc(message)}</div>
        <div class="confirm-actions">
          <button class="btn btn-ghost" data-act="no">Cancelar</button>
          <button class="btn ${danger ? 'btn-danger' : 'btn-primary'}" data-act="yes">${esc(confirmText)}</button>
        </div>
      </div>`;
    document.body.appendChild(wrap);
    requestAnimationFrame(() => wrap.classList.add('open'));
    const close = (val) => {
      wrap.classList.remove('open');
      setTimeout(() => wrap.remove(), 150);
      resolve(val);
    };
    wrap.addEventListener('click', (ev) => {
      if (ev.target === wrap) close(false);
      const a = ev.target.closest('[data-act]');
      if (!a) return;
      close(a.dataset.act === 'yes');
    });
  });
}

// ------------------------- Menú contextual genérico (ABM.md) -------------------------
// Un único menú por sección (ya renderizado en el DOM). Lo abrimos posicionándolo
// como `position: fixed` cerca del clic / botón hamburguesa. El módulo guarda el
// contexto (id del registro, datos) en `getCtxMenuData()` para que los handlers
// `data-action` puedan resolverlo al disparar.
let _ctxMenuActual = null;
let _ctxMenuData   = null;

function abrirCtxMenu(menuEl, x, y, data) {
  cerrarCtxMenu();
  if (!menuEl) return;
  _ctxMenuActual = menuEl;
  _ctxMenuData   = data || null;
  menuEl.classList.add('open');
  // medir y reposicionar dentro del viewport
  const rect = menuEl.getBoundingClientRect();
  const w    = rect.width  || 200;
  const h    = rect.height || 200;
  let nx = x, ny = y;
  if (nx + w > window.innerWidth  - 8) nx = window.innerWidth  - w - 8;
  if (ny + h > window.innerHeight - 8) ny = window.innerHeight - h - 8;
  if (nx < 8) nx = 8;
  if (ny < 8) ny = 8;
  // El menú es position:fixed, pero un ancestro con `transform` se convierte
  // en su containing block y hace que las coords dejen de ser de viewport
  // (caso típico: `.modal` usa transform para su animación de apertura, lo
  // que corría el menú ~300px lejos del puntero). Compensamos restando el
  // offset del ancestro transformado si existe.
  let ancestro = menuEl.parentElement;
  while (ancestro) {
    const t = getComputedStyle(ancestro).transform;
    if (t && t !== 'none') {
      const r = ancestro.getBoundingClientRect();
      nx -= r.left;
      ny -= r.top;
      break;
    }
    ancestro = ancestro.parentElement;
  }
  menuEl.style.left = nx + 'px';
  menuEl.style.top  = ny + 'px';
}

function cerrarCtxMenu() {
  if (!_ctxMenuActual) return;
  _ctxMenuActual.classList.remove('open');
  _ctxMenuActual = null;
  _ctxMenuData   = null;
}

function getCtxMenuData() { return _ctxMenuData; }

document.addEventListener('click', (ev) => {
  if (!_ctxMenuActual) return;
  if (_ctxMenuActual.contains(ev.target)) return;
  cerrarCtxMenu();
});
document.addEventListener('scroll', () => cerrarCtxMenu(), true);
window.addEventListener('resize',  () => cerrarCtxMenu());
document.addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape') cerrarCtxMenu();
});

// ------------------------- Router -------------------------
const routes = {};
function route(path, handler, title) {
  routes[path] = { handler, title: title || path };
}

// Mapeo ruta → permiso requerido para navegar.
// - `perm`   = slug exacto que el usuario debe tener.
// - `prefix` = habilita la ruta si el usuario tiene AL MENOS UN permiso con
//              ese prefijo (para landings de plataformas y Herramientas cuyo
//              contenido son sub-modulos con permisos propios).
// Rutas ausentes de este mapa quedan libres (fallback: si no se declaro, no se filtra).
