    const data = getCtxMenuData();
    if (!data) return;
    cerrarCtxMenu();
    if (b.dataset.action === 'consultar') abrirConsultaDcr(data.id);
    if (b.dataset.action === 'editar')    abrirAltaEdicionDcr(data.id);
    if (b.dataset.action === 'eliminar')  eliminarDcr(data.id);
