    clr.style.display = inp.value ? '' : 'none';
    evoCtFiltros.q = inp.value.trim();
    clearTimeout(evoCtBuscadorTimer);
    evoCtBuscadorTimer = setTimeout(() => { cargarEvoCt(); refrescarBadgeFiltrosEvoCt(); }, 250);
