    tgCanFiltros.q = inp.value.trim();
    clearTimeout(tgCanBuscadorTimer);
    tgCanBuscadorTimer = setTimeout(() => { cargarTgCan(); refrescarBadgeFiltrosTgCan(); }, 250);
